{
  "name": "@velnae/opencode-voice",
  "version": "0.1.1",
  "type": "module",
  "description": "OpenCode plugin for manual assistant-response readback using local Piper TTS",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/velnae/opencode-voice.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tts",
    "piper",
    "voice",
    "accessibility"
  ],
  "main": "dist/index.js",
  "exports": {
    ".": "./dist/index.js"
  },
  "files": [
    "dist/",
    "README.md",
    "package.json"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "prepack": "npm run build",
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "start": "node dist/index.js"
  },
  "devDependencies": {
    "@types/node": "^22.4.0",
    "typescript": "^5.6.3"
  }
}
